// 1. 匿名管道示例
#include <unistd.h>
#include <stdio.h>
#include <string.h>

int main() {
    int fd[2];
    pipe(fd); // fd[0]读, fd[1]写

    if (fork() == 0) {
        close(fd[0]);
        char *msg = "Hello from child";
        write(fd[1], msg, strlen(msg));
        close(fd[1]);
    } else {
        close(fd[1]);
        char buf[100];
        int n = read(fd[0], buf, sizeof(buf));
        buf[n] = '\0';
        printf("Parent received: %s\n", buf);
        close(fd[0]);
    }
    return 0;
}

// 2. 共享内存示例（POSIX）
#include <sys/mman.h>
#include <fcntl.h>

// 创建共享内存
int fd = shm_open("/myshm", O_CREAT | O_RDWR, 0666);
ftruncate(fd, 4096);
int *ptr = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);

// 写入数据
*ptr = 42;

// 读取数据（另一个进程）
int fd2 = shm_open("/myshm", O_RDONLY, 0666);
int *ptr2 = mmap(NULL, 4096, PROT_READ, MAP_SHARED, fd2, 0);
printf("Value: %d\n", *ptr2); // 输出 42
